import app from 'flarum/common/app';
import MobileTabComponent from '../../common/components/MobileTabComponent';
import MobileTabItem from './MobileTabItem';
export default class ForumNotificationsTabItem extends MobileTabComponent {
  view() {
    if (!app.session.user) return;
    const unread = this.getUnreadCount();
    const {
      icon,
      label,
      href
    } = this.attrs.definition;
    return m(MobileTabItem, {
      href: typeof href === 'function' ? href() : href,
      icon: icon
    }, unread ? m("span", {
      className: "Bubble"
    }, unread) : '', label);
  }
  getUnreadCount() {
    return app.session.user.unreadNotificationCount() || null;
  }
}
flarum.reg.add('acpl-mobile-tab', 'forum/components/ForumNotificationsTabItem', ForumNotificationsTabItem);